{
  "decisions": [
    {
      "surface": "y-o-y growth",
      "action": "create",
      "measure": "year over year growth rate",
      "description": "A percentage rate representing the change in a value compared to the same period in the previous year."
    },
    {
      "surface": "share in real gdp",
      "action": "create",
      "measure": "share in real gdp",
      "description": "The proportion of a specific economic component relative to the total real GDP."
    },
    {
      "surface": "is as a percentage of the long-period average (lpa)",
      "action": "create",
      "measure": "percentage of long period average",
      "description": "A ratio expressing a value as a percentage of the long-period average."
    },
    {
      "surface": "percentage of capacity",
      "action": "create",
      "measure": "percentage of capacity",
      "description": "A ratio representing the current level relative to the maximum capacity."
    },
    {
      "surface": "percentage expansion",
      "action": "create",
      "measure": "percentage expansion",
      "description": "A percentage rate representing the growth or increase of a quantity."
    },
    {
      "surface": "percentage increase over final estimates of 2023-24",
      "action": "create",
      "measure": "percentage increase over final estimates",
      "description": "A percentage rate representing the increase relative to a specific prior year's final estimate."
    },
    {
      "surface": "first advance estimates",
      "action": "create",
      "measure": "first advance estimate",
      "description": "The initial projected quantity of production or output."
    },
    {
      "surface": "second advance estimate for 2024-25",
      "action": "create",
      "measure": "second advance estimate",
      "description": "The second projected quantity of production or output for a specific period."
    },
    {
      "surface": "increased",
      "action": "create",
      "measure": "percentage change",
      "description": "A generic measure for a percentage increase."
    },
    {
      "surface": "averaged",
      "action": "create",
      "measure": "average percentage",
      "description": "The mean value of a percentage over a specified period."
    },
    {
      "surface": "contributed to headline inflation",
      "action": "create",
      "measure": "contribution to headline inflation",
      "description": "The percentage contribution of a specific component to the total headline inflation rate."
    },
    {
      "surface": "recorded deflation of",
      "action": "create",
      "measure": "deflation rate",
      "description": "A percentage rate representing a decrease in price levels."
    },
    {
      "surface": "inflation",
      "action": "create",
      "measure": "inflation rate",
      "description": "The rate of increase in prices over a given period."
    },
    {
      "surface": "contribution to headline inflation",
      "action": "link",
      "measure": "contribution to headline inflation",
      "description": "Linking to the existing canonical measure for contribution to headline inflation."
    },
    {
      "surface": "average inflation",
      "action": "create",
      "measure": "average inflation rate",
      "description": "The mean inflation rate over a specified period."
    },
    {
      "surface": "growth adjusted for the first-round impact of the crr reduction",
      "action": "create",
      "measure": "adjusted growth rate",
      "description": "A growth rate adjusted for specific policy impacts like CRR reduction."
    },
    {
      "surface": "expansion",
      "action": "create",
      "measure": "monetary expansion amount",
      "description": "The currency amount representing an increase in a financial asset or balance."
    },
    {
      "surface": "outstanding",
      "action": "create",
      "measure": "outstanding amount",
      "description": "The total currency amount currently held or remaining."
    },
    {
      "surface": "total observations",
      "action": "create",
      "measure": "total count of observations",
      "description": "The total number of data points in a statistical model."
    },
    {
      "surface": "fresh issuances of cps",
      "action": "create",
      "measure": "fresh issuances of commercial papers",
      "description": "The currency value of new commercial paper issuances."
    },
    {
      "surface": "fpis invested in debt instruments",
      "action": "create",
      "measure": "fpi investment in debt instruments",
      "description": "The currency amount invested by Foreign Portfolio Investors in debt instruments."
    },
    {
      "surface": "amount raised",
      "action": "create",
      "measure": "amount raised",
      "description": "The total currency amount collected through issuances or funding."
    },
    {
      "surface": "rise",
      "action": "create",
      "measure": "percentage rise",
      "description": "A percentage rate representing an increase."
    },
    {
      "surface": "net fpi outflow",
      "action": "create",
      "measure": "net fpi outflow",
      "description": "The net currency amount of capital withdrawn by Foreign Portfolio Investors."
    }
  ]
}
